// Fake L813 for testing index.html without hardware: injects navigator.bluetooth and replays two captured recordings.
(() => {
  const B = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
  const FIX = {
    '01_20260215060045': { raw: B(''), size: 202284 },
    '01_20261009200942': { raw: B(''), size: 221740 },
  };
  const files = Object.entries(FIX).map(([name, f]) => ({ name, size: f.size }));
  const enc = s => Uint8Array.from(s, c => c.charCodeAt(0));
  const i32 = n => Uint8Array.of(n >>> 24, n >>> 16 & 255, n >>> 8 & 255, n & 255);
  const hex = b => Array.from(b, x => x.toString(16).padStart(2, '0')).join('');
  window.__writes = []; window.__mock = { files, fixtures: FIX };
  const dev = new EventTarget(); dev.id = 'MOCK'; dev.name = 'L813';
  class Char extends EventTarget {
    constructor(uuid) { super(); this.uuid = uuid; }
    async startNotifications() { return this; }
    notify(b) { this.value = new DataView(Uint8Array.from(b).buffer); this.dispatchEvent(new Event('characteristicvaluechanged')); }
    async writeValueWithoutResponse(v) { const f = new Uint8Array(v.buffer ? v.buffer.slice(v.byteOffset, v.byteOffset + v.byteLength) : v); window.__writes.push(hex(f)); setTimeout(() => onWrite(f), 3); }
  }
  const mk = p => new Char(p + '-2233-4455-6677-889912345678');
  const ch = { wr: mk('0011202a'), rsp: mk('0011203a'), file: mk('0011204a'), live: mk('0011201a') };
  const rsp = (key, payload = []) => ch.rsp.notify([0xAA, 0x55, payload.length + 1, key, ...payload]);
  const entry = f => [...enc(f.name), ...i32(f.size)];
  async function onWrite(f) {
    const key = f[3], p = f.slice(4);
    switch (key) {
      case 1: rsp(1, enc('813012511270165')); break;
      case 18: rsp(18, enc('2.1.0')); break;
      case 14: rsp(14, [100]); break;
      case 5: for (const x of files) ch.rsp.notify([0xAA, 0x55, 0x13, 5, ...entry(x)]); rsp(6); break;
      case 7: {
        const name = String.fromCharCode(...p.slice(0, p.length - 4)), fx = FIX[name];
        if (!fx) { rsp(253); break; }
        ch.rsp.notify([0xAA, 0x55, 0x13, 7, ...enc(name), ...i32(fx.raw.length)]);
        for (let i = 0; i < fx.raw.length; i += 244) { ch.file.notify(fx.raw.slice(i, i + 244)); if (i % 2440 === 0) await new Promise(r => setTimeout(r, 1)); }
        rsp(9); break;
      }
      case 10: { const name = String.fromCharCode(...p); const i = files.findIndex(x => x.name === name); if (i >= 0) files.splice(i, 1); rsp(10); break; }
      case 4: rsp(4, entry({ name: '01_20261010101010', size: 64044 })); break;
    }
  }
  const svc = { getCharacteristic: async u => Object.values(ch).find(c => c.uuid === u) };
  const server = { getPrimaryService: async u => { if (u !== '0011200a-2233-4455-6677-889912345678') throw new Error('no service'); return svc; } };
  dev.gatt = { connect: async () => server, disconnect() { dev.dispatchEvent(new Event('gattserverdisconnected')); } };
  Object.defineProperty(navigator, 'bluetooth', { configurable: true, value: { requestDevice: async opts => { window.__lastRequest = opts; return dev; } } });
})();
